@Injectable()
export class PermissionsGuard implements CanActivate {
  constructor(private reflector: Reflector, private abilities: CaslAbilityFactory) {}

  canActivate(ctx: ExecutionContext): boolean {
    const required = this.reflector.getAllAndOverride<Permission[]>(PERMISSIONS_KEY, [
      ctx.getHandler(), ctx.getClass(),
    ]);
    if (!required) return false;                       // deny by default
    const { user } = ctx.switchToHttp().getRequest();
    const ability = this.abilities.createForUser(user);        // decision
    return required.every((p) => ability.can(p.action, p.subject));
  }
}
